UPDATE "public"."case_item" SET "reference_id" = "__pine_source__"."__pine_value_1__", "title" = "__pine_source__"."__pine_value_2__", "updated_at" = NOW() FROM ( WITH "processing" AS ( SELECT "ci_0"."id", "ci_0"."tenant_id", "ci_0"."request_id", "ci_0"."company_id", "ci_0"."source_request_file_id", "ci_0"."created_at" FROM "public"."case_item" AS "ci_0" WHERE "ci_0"."case_item_type" = 'TextQuestionnaire' AND "ci_0"."status" = 'Pending' AND "ci_0"."reference_id" IS NULL AND "ci_0"."source_request_file_id" IS NOT NULL AND "ci_0"."deleted_at" IS NULL ), "case_item_reference_ids" AS ( SELECT "linked"."reference_id" FROM "public"."case_item" AS "linked" WHERE "linked"."deleted_at" IS NULL AND "linked"."reference_id" IS NOT NULL ), "candidates" AS ( SELECT "p"."id" AS "item_id", "r"."id" AS "request_id", CASE WHEN ("r"."source_request_file_id" = "p"."source_request_file_id") THEN 1 ELSE 2 END AS "tier" FROM "processing" AS "p" JOIN "questions"."questionnaire_request" AS "r" ON "p"."tenant_id" = "r"."tenant_id" AND "p"."request_id" = "r"."request_id" AND "p"."company_id" = "r"."company_id" WHERE "r"."deleted_at" IS NULL AND "r"."status" IN ('In Progress', 'Completed') AND "r"."source_request_file_id" IS NOT NULL AND "r"."created_at" >= "p"."created_at" AND "r"."id" NOT IN ( SELECT "reference_id" FROM "case_item_reference_ids" ) ), "best_tier" AS ( SELECT "candidates"."item_id", MIN("candidates"."tier") AS "tier" FROM "candidates" AS "candidates" GROUP BY "candidates"."item_id" ), "best_candidates" AS ( SELECT "c"."item_id", "c"."request_id", "c"."tier" FROM "candidates" AS "c" JOIN "best_tier" AS "b" ON "c"."item_id" = "b"."item_id" AND "c"."tier" = "b"."tier" ), "result_1" AS ( SELECT "best_candidates"."item_id", MIN("best_candidates"."request_id"::text) AS "min_request_id", MIN("best_candidates"."tier") AS "tier", COUNT(1) AS "count" FROM "best_candidates" AS "best_candidates" GROUP BY "best_candidates"."item_id" ), "picked" AS ( SELECT "result_1"."item_id", "result_1"."min_request_id"::uuid AS "request_id", "result_1"."tier" FROM "result_1" AS "result_1" WHERE "result_1"."count" = '1' ), "picked_item_ids" AS ( SELECT "p"."item_id" FROM "picked" AS "p" JOIN "best_candidates" AS "other" ON "p"."request_id" = "other"."request_id" WHERE "other"."item_id" != "p"."item_id" AND ("p"."tier" = '2' OR "other"."tier" = '1') ), "unambiguous" AS ( SELECT "p"."item_id", "p"."request_id" FROM "picked" AS "p" WHERE "p"."item_id" NOT IN ( SELECT "item_id" FROM "picked_item_ids" ) ) SELECT "ci"."id" AS "__pine_key_1__", "u"."request_id" AS "__pine_value_1__", "q"."name" AS "__pine_value_2__" FROM "public"."case_item" AS "ci" JOIN "unambiguous" AS "u" ON "ci"."id" = "u"."item_id" JOIN "questions"."questionnaire_request" AS "r" ON "u"."request_id" = "r"."id" JOIN "questions"."questionnaire" AS "q" ON "r"."questionnaire_id" = "q"."id" WHERE "ci"."reference_id" IS NULL ) AS "__pine_source__" WHERE "case_item"."reference_id" IS NULL AND "__pine_source__"."__pine_key_1__" = "case_item"."id";
